1464 | def walk(self, where="/"):
1465 |         """
1466 |         Walk the pytables group hierarchy for pandas objects.
1467 | 
1468 |         This generator will yield the group path, subgroups and pandas object
1469 |         names for each group.
1470 | 
1471 |         Any non-pandas PyTables objects that are not a group will be ignored.
1472 | 
1473 |         The `where` group itself is listed first (preorder), then each of its
1474 |         child groups (following an alphanumerical order) is also traversed,
1475 |         following the same procedure.
1476 | 
1477 |         Parameters
1478 |         ----------
1479 |         where : str, default "/"
1480 |             Group where to start walking.
1481 | 
1482 |         Yields
1483 |         ------
1484 |         path : str
1485 |             Full path to a group (without trailing '/').
1486 |         groups : list
1487 |             Names (strings) of the groups contained in `path`.
1488 |         leaves : list
1489 |             Names (strings) of the pandas objects contained in `path`.
1490 |         """
1491 |         _tables()
1492 |         self._check_if_open()
1493 |         assert self._handle is not None  # for mypy
1494 |         assert _table_mod is not None  # for mypy
1495 | 
1496 |         for g in self._handle.walk_groups(where):
1497 |             if getattr(g._v_attrs, "pandas_type", None) is not None:
1498 |                 continue
1499 | 
1500 |             groups = []
1501 |             leaves = []
1502 |             for child in g._v_children.values():
1503 |                 pandas_type = getattr(child._v_attrs, "pandas_type", None)
1504 |                 if pandas_type is None:
1505 |                     if isinstance(child, _table_mod.group.Group):
1506 |                         groups.append(child._v_name)
1507 |                 else:
1508 |                     leaves.append(child._v_name)
1509 | 
1510 |             yield (g._v_pathname.rstrip("/"), groups, leaves)
